/* Isolated portal demonstrations never call production write endpoints. */
const baseRender=render,baseShell=updateShell,baseBind=bind;
let authChecked=false,schoolLoginBusy=false,activeRealRole=null;
const examples={
 users:[{id:'mek',name:'Mek',roles:['student'],email:'mek@example.test'},{id:'fah',name:'Fah',roles:['student'],email:'fah@example.test'},{id:'mali',name:'Mali',roles:['teacher'],email:'mali@example.test'},{id:'pat',name:'Pat',roles:['parent'],email:'pat@example.test'}],
 courses:[{id:'science',teacher:'Mali',published:true},{id:'physics',teacher:'Nina',published:true},{id:'chemistry',teacher:'Nina',published:false}],
 links:[{parent:'pat',student:'mek',verified:true},{parent:'pat',student:'fah',verified:true}],
 assignments:[{student:'mek',course:'science',expiry:'2026-12-31',active:true},{student:'fah',course:'physics',expiry:'2026-11-30',active:true}],
 submissions:[{id:'work1',student:'mek',course:'science',text:'I noticed that ice floats. I would compare its mass and volume with liquid water.',score:null,feedback:'',returned:false}],
 questions:[{id:'q1',student:'mek',course:'science',text:'Why does ice float if it is solid?',reply:''}],
 messages:[{id:'m1',parent:'pat',student:'mek',course:'science',text:'Which topic should we review at home?',reply:''}],
 enrollment:[{student:'fah',course:'chemistry',status:'pending'}],child:'mek',lesson:3,complete:new Set([0,1,2]),score:null,attempts:0,media:[],branding:structuredClone(DEFAULT_APPEARANCE),profiles:{admin:{name:'Alex',bio:''},teacher:{name:'Mali',bio:''},student:{name:'Mek',bio:''},parent:{name:'Pat',bio:''}}
};
const allowedRealRoles=()=>Array.isArray(session.roles)?session.roles.filter(r=>['admin','teacher','student','parent'].includes(r)):(['admin','teacher','student','parent'].includes(session.role)?[session.role]:[]);
const realRole=()=>allowedRealRoles().includes(activeRealRole)?activeRealRole:allowedRealRoles()[0];
const demoRoute=()=>route()[0]==='demo'&&['admin','teacher','student','parent'].includes(route()[1]);
const sampleName=id=>id==='mek'?t('Mek','เมฆ'):id==='fah'?t('Fah','ฟ้า'):esc(examples.users.find(u=>u.id===id)?.name||id);
const demoCourse=id=>examples.courses.find(c=>c.id===id);
const courseTitle=id=>DEFAULT_CONTENT[id]?tx(content(id).title):tx(demoCourse(id)?.title)||id;
const accessFor=(student,course)=>examples.assignments.some(a=>a.student===student&&a.course===course&&a.active&&(a.expiry==='unlimited'||new Date(a.expiry+'T23:59:59')>=new Date()));
const teacherCan=(student,course)=>demoCourse(course)?.teacher==='Mali'&&examples.assignments.some(a=>a.student===student&&a.course===course&&a.active);
const children=()=>examples.links.filter(l=>l.parent==='pat'&&l.verified).map(l=>l.student);
const personProgress=id=>id==='mek'?examples.complete.size:0;
const demoPath=(page,r=route()[1])=>'demo/'+r+'/'+page;
route=()=>((location.hash.slice(1)||'home').split('?')[0]).split('/');
function nextPath(){const value=new URLSearchParams(location.hash.split('?')[1]||'').get('next');return value&&/^portal\/[a-z-]+$/.test(value)?value:'portal/overview'}
function sampleBanner(){return `<div class="sample-banner"><strong>${t('Demo — Sample Data','สาธิต — ข้อมูลตัวอย่าง')}</strong><span>${t('Fictional people. Changes stay in this tab. No messages or invitations are sent.','ข้อมูลบุคคลสมมติ การเปลี่ยนแปลงอยู่ในแท็บนี้ ไม่มีการส่งข้อความหรือคำเชิญ')}</span><a href="#demo">${t('Change demo role','เปลี่ยนบทบาทสาธิต')} ↗</a></div>`}
function schoolLogin(){return `<div class="container login-layout"><section><div class="eyebrow">HEADSTART ACADEMICS</div><h1>${t('A little further.<br>Every day.','ก้าวไปอีกนิด<br>ในทุกวัน')}</h1><p>${t('Your lessons, progress, and conversations, all in one learning space.','บทเรียน พัฒนาการ และการพูดคุยในพื้นที่การเรียนรู้เดียวกัน')}</p><div class="login-demo"><h3>${t('Take a look around','ลองสำรวจดู')}</h3><p>${t('Explore four fictional portals without creating an account.','สำรวจสี่พื้นที่ผู้ใช้ด้วยข้อมูลสมมติโดยไม่ต้องสร้างบัญชี')}</p>${button(t('Explore Demo','สำรวจระบบสาธิต'),'demo','')}</div></section><section class="auth-box"><h2>${t('Log In','เข้าสู่ระบบ')}</h2><p>${t('School account','บัญชีโรงเรียน')}</p><form id="school-login" autocomplete="on">${field('email',t('Email','อีเมล'),'','email')}<label>${t('Password','รหัสผ่าน')}<div class="password-field"><input name="password" type="password" required minlength="8" autocomplete="current-password" aria-describedby="login-connection"><button type="button" id="password-toggle" aria-pressed="false">${t('Show','แสดง')}</button></div></label><a class="text-link" href="#reset">${t('Forgot Password?','ลืมรหัสผ่าน?')}</a><div id="login-error" role="alert"></div><button class="primary" style="margin-top:24px" ${schoolLoginBusy?'disabled':''}>${t('Log In','เข้าสู่ระบบ')}</button></form><p id="login-connection" class="service-note">${t('School email/password sign-in is not connected. Do not enter a real password.','ยังไม่เชื่อมต่อการเข้าสู่ระบบโรงเรียนด้วยอีเมลและรหัสผ่าน อย่ากรอกรหัสผ่านจริง')}</p><p>${t('New to Headstart?','เริ่มต้นกับ Headstart?')} <a class="text-link" href="#register">${t('Create Account','สร้างบัญชี')}</a></p><div class="management-login"><h3>${t('Authorized website management','การจัดการเว็บไซต์สำหรับผู้มีสิทธิ์')}</h3>${allowedRealRoles().length?button(t('My Dashboard','แดชบอร์ดของฉัน'),nextPath()):online?`<a class="button" target="_top" href="/signin-with-chatgpt?return_to=${encodeURIComponent('/#'+nextPath())}">${t('Continue with ChatGPT','ดำเนินการต่อด้วย ChatGPT')}</a>`:notice(t('Cloud sign-in is unavailable in this local preview.','การเข้าสู่ระบบคลาวด์ใช้ไม่ได้ในตัวอย่างเครื่องนี้'))}<p>${t('This uses your verified account and assigned permissions. It is separate from the demo.','ใช้บัญชีที่ยืนยันและสิทธิ์ที่ได้รับมอบหมาย แยกจากระบบสาธิต')}</p></div></section></div>`}
function accountScreen(kind){const reset=kind==='reset';return `<div class="container narrow">${heading(reset?t('Password reset','รีเซ็ตรหัสผ่าน'):t('Create Account','สร้างบัญชี'),reset?t('Let’s get you back to learning.','กลับมาเรียนรู้กันอีกครั้ง'):t('Begin your Headstart journey.','เริ่มต้นเส้นทาง Headstart'))}<div class="auth-box"><form id="${reset?'password-reset':'school-registration'}">${!reset?`<div class="two">${field('first',t('First name','ชื่อ'))}${field('last',t('Last name','นามสกุล'))}</div>`:''}${field('email',t('Email','อีเมล'),'','email')}${!reset?`<label>${t('Account type','ประเภทบัญชี')}<select name="role" id="registration-role"><option value="student">${roleName('student')}</option><option value="parent">${roleName('parent')}</option></select></label><div id="registration-student"><div class="two">${field('age',t('Age','อายุ'),'','number')}${field('grade',t('Grade / class','ระดับชั้น'))}</div>${field('school',t('School','โรงเรียน'))}${field('parentEmail',t('Parent email','อีเมลผู้ปกครอง'),'','email')}</div>${field('phone',t('Phone','โทรศัพท์'))}${field('other',t('Other contact (optional)','ช่องทางติดต่ออื่น (ไม่บังคับ)'),'','text',false)}<p>${t('Teacher and administrator roles are assigned by an authorized administrator. Parent access requires a verified relationship.','ผู้ดูแลที่ได้รับอนุญาตเป็นผู้มอบหมายบทบาทครูและผู้ดูแล สิทธิ์ผู้ปกครองต้องยืนยันความสัมพันธ์')}</p>`:''}<div id="account-result" role="alert"></div><button class="primary">${reset?t('Request reset link','ขอลิงก์ตั้งรหัสผ่านใหม่'):t('Create Account','สร้างบัญชี')}</button></form>${notice(t('Account creation and password-reset email delivery are not connected. This form does not create an account or send email. Use fictional information only.','ยังไม่เชื่อมต่อการสร้างบัญชีและอีเมลรีเซ็ตรหัสผ่าน แบบฟอร์มนี้ไม่สร้างบัญชีหรือส่งอีเมล ใช้ข้อมูลสมมติเท่านั้น'),true)}<a class="text-link" href="#login">${t('Back to Log In','กลับไปเข้าสู่ระบบ')} ↗</a></div></div>`}
function chooseDemo(){return `<div class="container">${heading(t('Explore Demo','สำรวจระบบสาธิต'),t('One school. Four perspectives.','หนึ่งโรงเรียน สี่มุมมอง'),t('Try the main workflows with fictional data. This is not authentication.','ทดลองขั้นตอนหลักด้วยข้อมูลสมมติ นี่ไม่ใช่การยืนยันตัวตน'))}${sampleBanner()}<div class="demo-choices">${[['admin','01',t('Keep the school moving','ดูแลการดำเนินงานโรงเรียน'),t('Invite sample users, assign courses, and link families.','เชิญผู้ใช้ตัวอย่าง มอบหมายหลักสูตร และเชื่อมครอบครัว')],['teacher','02',t('Make the next step clear','ช่วยให้ก้าวต่อไปชัดเจน'),t('Review work, give feedback, and answer questions.','ตรวจงาน ให้ข้อเสนอแนะ และตอบคำถาม')],['student','03',t('Pick up where you left off','เรียนต่อจากครั้งที่แล้ว'),t('Continue a lesson, submit work, and see your progress.','เรียนต่อ ส่งงาน และดูพัฒนาการ')],['parent','04',t('See progress together','เห็นพัฒนาการไปด้วยกัน'),t('Follow each linked child’s learning and talk to their teacher.','ติดตามการเรียนรู้ของบุตรหลานที่เชื่อมบัญชีและพูดคุยกับครู')]].map(([r,n,title,desc])=>`<article class="card card-body"><div class="role-number">${n}</div><span class="tag">${roleName(r)}</span><h2>${title}</h2><p>${desc}</p>${button(t('Demo as ','สาธิตเป็น')+roleName(r),'demo/'+r+'/overview')}</article>`).join('')}</div></div>`}
function menuFor(r){const labels={overview:r==='student'?t('My Learning','การเรียนรู้ของฉัน'):t('Overview','ภาพรวม'),users:t('Users','ผู้ใช้'),courses:r==='teacher'?t('My Courses','หลักสูตรของฉัน'):t('Courses','หลักสูตร'),access:t('Course Assignments','มอบหมายหลักสูตร'),assessments:t('Assessments','แบบทดสอบ'),links:t('Parent–Student Links','เชื่อมผู้ปกครอง–นักเรียน'),reports:t('Reports','รายงาน'),events:t('Events','กิจกรรม'),content:t('Website Content','เนื้อหาเว็บไซต์'),media:t('Media Library','คลังสื่อ'),appearance:t('Website Appearance','รูปลักษณ์เว็บไซต์'),settings:t('Settings','การตั้งค่า'),students:t('Students','นักเรียน'),assignments:t('Assignments','งานที่มอบหมาย'),questions:t('Questions','คำถาม'),communication:t('Parent Communication','สื่อสารกับผู้ปกครอง'),profile:t('Profile','โปรไฟล์'),results:t('Results & Certificates','ผลและใบประกาศ'),progress:t('Learning Progress','พัฒนาการเรียนรู้'),work:t('Results & Assignments','ผลและงานที่มอบหมาย'),feedback:t('Teacher Feedback','ข้อเสนอแนะจากครู'),messages:t('Messages','ข้อความ')};const ids={admin:['overview','users','courses','access','assessments','links','reports','events','content','media','appearance','settings'],teacher:['overview','courses','students','assignments','assessments','questions','communication','media','profile'],student:['overview','assignments','assessments','questions','results','profile'],parent:['overview','progress','work','feedback','messages','profile']};return ids[r].map(id=>[id,labels[id]])}
function demoPortal(r,page='overview',item){if(!['admin','teacher','student','parent'].includes(r))return chooseDemo();const menus=menuFor(r);if(!menus.some(([id])=>id===page)&&!(r==='student'&&page==='learn'))return empty(t('Page not available for this demo role','หน้านี้ไม่พร้อมสำหรับบทบาทสาธิตนี้'),t('Use the role’s navigation.','เลือกจากเมนูของบทบาทนี้'));const title=menus.find(m=>m[0]===page)?.[1]||t('Continue Learning','เรียนต่อ');return `${sampleBanner()}<div class="portal portal-v3"><aside class="sidebar"><div class="profile"><span class="avatar">${r==='teacher'?'M':r==='student'?'M':r==='parent'?'P':'A'}</span><b>${r==='teacher'?'Mali':r==='student'?sampleName('mek'):r==='parent'?'Pat':'Alex'}</b><small>${roleName(r)} · ${t('Fictional account','บัญชีสมมติ')}</small></div>${menus.map(([id,label])=>`<a href="#demo/${r}/${id}" class="${page===id?'active':''}">${label}</a>`).join('')}<a href="#home">← ${t('School website','เว็บไซต์โรงเรียน')}</a></aside><div class="portal-content"><div class="portal-topbar"><div><div class="eyebrow">HEADSTART / ${roleName(r)}</div><h1>${title}</h1></div><div class="portal-controls"><div class="language-switch">${['en','th'].map(l=>`<button data-portal-lang="${l}" aria-pressed="${l===lang}">${l.toUpperCase()}</button>`).join('')}</div><details class="account-dropdown"><summary>${t('Demo account','บัญชีสาธิต')}</summary><div><a href="#demo/${r}/${r==='admin'?'settings':'profile'}">${t('Profile','โปรไฟล์')}</a><a href="#demo">${t('Switch demo role','เปลี่ยนบทบาทสาธิต')}</a><a href="#login">${t('Exit Demo','ออกจากระบบสาธิต')}</a></div></details></div></div>${r==='parent'?childSelector():''}${demoBody(r,page,item)}</div></div>`}
function childSelector(){const ids=children();if(!ids.includes(examples.child))examples.child=ids[0]||null;return `<div class="child-picker"><span class="avatar">${examples.child==='mek'?'M':'F'}</span><label>${t('Viewing your verified linked child','ดูบุตรหลานที่ยืนยันความสัมพันธ์แล้ว')}<select id="demo-child">${ids.map(id=>`<option value="${id}" ${examples.child===id?'selected':''}>${sampleName(id)}</option>`).join('')}</select></label><span class="tag">${t('Verified link · sample','ยืนยันแล้ว · ตัวอย่าง')}</span></div>`}
function learningCard(a,student='mek'){const id=a.course,c=content(id),cover=c.image?picture(c.image):`<div class="course-art ${id==='physics'?'physics':''}"><span class="formula">${id==='science'?'H₂O':'F = ma'}</span></div>`,progress=student==='mek'?examples.complete.size:0;return `<article class="card learning-card">${cover}<div class="card-body"><span class="tag">${t('Assigned course','หลักสูตรที่มอบหมาย')}</span><h3>${esc(courseTitle(id))}</h3><p>${t('Teacher','ครู')}: ${esc(demoCourse(id)?.teacher||'—')}</p><progress value="${progress}" max="8" aria-label="${t('Progress','ความก้าวหน้า')}"></progress><p>${progress}/8 ${t('lessons complete','บทเรียนที่เสร็จ')} · ${Math.round(progress/8*100)}%</p><p>${t('Access until','สิทธิ์ถึง')}: ${a.expiry==='unlimited'?t('Unlimited','ไม่จำกัด'):new Date(a.expiry).toLocaleDateString(lang==='th'?'th-TH':'en-GB')}</p>${route()[1]==='student'?button(t('Continue Learning','เรียนต่อ'),'demo/student/learn/'+id):''}</div></article>`}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(cells=>`<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function demoBody(r,page,item){if(page==='profile')return profileDemo(r);if(r==='admin')return adminDemo(page);if(r==='teacher')return teacherDemo(page,item);if(r==='parent')return parentDemo(page);return studentDemo(page,item)}
function adminDemo(page){if(page==='overview')return `<div class="welcome-strip"><div><h2>${t('A clear view of the school day.','มองเห็นงานของโรงเรียนอย่างชัดเจน')}</h2><p>${t('Start with the people and courses that need attention.','เริ่มจากผู้เรียนและหลักสูตรที่ต้องดูแล')}</p></div><div class="actions">${button(t('Add User','เพิ่มผู้ใช้'),'demo/admin/users')}${button(t('Create Course','สร้างหลักสูตร'),'demo/admin/courses','')}${button(t('Assign Course','มอบหมายหลักสูตร'),'demo/admin/access','')}</div></div>${stats([[examples.users.filter(u=>u.roles.includes('student')).length,t('Active sample students','นักเรียนตัวอย่างที่ใช้งาน')],[examples.courses.filter(c=>c.published).length,t('Published sample courses','หลักสูตรตัวอย่างที่เผยแพร่')],[examples.enrollment.filter(e=>e.status==='pending').length,t('Enrollment requests','คำขอเรียน')],[examples.users.filter(u=>u.roles.includes('student')&&!examples.assignments.some(a=>a.student===u.id&&a.active)).length,t('Awaiting assignment','รอมอบหมายหลักสูตร')]])}<div class="grid"><section class="panel"><h3>${t('Enrollment to review','คำขอเรียนที่รอตรวจสอบ')}</h3>${examples.enrollment.map(e=>`<div class="task-row"><div><b>${sampleName(e.student)}</b><p>${esc(courseTitle(e.course))} · ${t('Pending review','รอตรวจสอบ')}</p></div><a class="text-link" href="#demo/admin/access">${t('Assign','มอบหมาย')} ↗</a></div>`).join('')}</section><section class="panel"><h3>${t('Course completion','ความสำเร็จของหลักสูตร')}</h3><p>Science Explorer · ${examples.complete.size}/8 ${t('lessons','บทเรียน')}</p><progress value="${examples.complete.size}" max="8"></progress><p>${t('Completed courses','หลักสูตรที่เรียนครบ')}: ${examples.complete.size===8?1:0}</p></section></div><section class="panel"><h3>${t('Upcoming workshop','เวิร์กช็อปถัดไป')}</h3><p>Science Discovery Workshop · 17 ${t('October 2026','ตุลาคม 2569')} · ${6+demo.registrations.filter(x=>!x.cancelled).length}/12 ${t('registrations','ผู้ลงทะเบียน')}</p>${button(t('Manage registrations','จัดการการลงทะเบียน'),'demo/admin/events','')}</section>`;
if(page==='users')return `<div class="panel"><h2>${t('People & assigned roles','ผู้ใช้และบทบาทที่มอบหมาย')}</h2>${table([t('Name','ชื่อ'),t('Roles','บทบาท'),t('Email','อีเมล')],examples.users.map(u=>[esc(u.name),u.roles.map(roleName).join(', '),esc(u.email)]))}</div><div class="panel"><h2>${t('Add or invite a sample user','เพิ่มหรือเชิญผู้ใช้ตัวอย่าง')}</h2><form id="demo-user">${field('name',t('Name','ชื่อ'))}${field('email',t('Fictional email','อีเมลสมมติ'),'','email')}<label>${t('Assigned role','บทบาทที่มอบหมาย')}<select name="role">${['student','parent','teacher','admin'].map(r=>`<option value="${r}">${roleName(r)}</option>`).join('')}</select></label><button class="primary">${t('Create sample invitation','สร้างคำเชิญตัวอย่าง')}</button><p>${t('No invitation is sent and no real account or permission is created.','ไม่มีการส่งคำเชิญ สร้างบัญชีจริง หรือให้สิทธิ์จริง')}</p></form><h3>${t('Change sample roles','เปลี่ยนบทบาทตัวอย่าง')}</h3><form id="demo-roles"><label>${t('User','ผู้ใช้')}<select name="user">${examples.users.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><label>${t('Add an assigned role','เพิ่มบทบาทที่มอบหมาย')}<select name="role">${['student','parent','teacher','admin'].map(r=>`<option value="${r}">${roleName(r)}</option>`).join('')}</select></label><button class="button">${t('Update sample roles','อัปเดตบทบาทตัวอย่าง')}</button></form></div>`;
if(page==='courses')return `<div class="panel">${table([t('Course','หลักสูตร'),t('Teacher','ครู'),t('Status','สถานะ')],examples.courses.map(c=>[esc(courseTitle(c.id)),esc(c.teacher),c.published?t('Published','เผยแพร่'):t('Draft','ร่าง')]))}</div><div class="panel"><h2>${t('Create a sample course','สร้างหลักสูตรตัวอย่าง')}</h2><form id="demo-course"><div class="two">${field('en',t('English title','ชื่อภาษาอังกฤษ'))}${field('th',t('Thai title (optional)','ชื่อภาษาไทย (ไม่บังคับ)'),'','text',false)}</div><label>${t('Teacher','ครู')}<select name="teacher"><option>Mali</option><option>Nina</option></select></label><label>${t('Status','สถานะ')}<select name="status"><option value="draft">${t('Draft','ร่าง')}</option><option value="published">${t('Published','เผยแพร่')}</option></select></label><button class="primary">${t('Save sample course','บันทึกหลักสูตรตัวอย่าง')}</button></form></div>`;
if(page==='access')return `<div class="panel"><h2>${t('Course access is assigned here','กำหนดสิทธิ์หลักสูตรที่นี่')}</h2>${table([t('Student','นักเรียน'),t('Course','หลักสูตร'),t('Access','สิทธิ์'),t('Action','จัดการ')],examples.assignments.map((a,i)=>[sampleName(a.student),esc(courseTitle(a.course)),a.active?esc(a.expiry):t('Revoked','เพิกถอน'),`<button class="button small" data-revoke="${i}">${a.active?t('Revoke','เพิกถอน'):t('Restore','คืนสิทธิ์')}</button>`]))}<form id="demo-access"><div class="two"><label>${t('Student','นักเรียน')}<select name="student">${examples.users.filter(u=>u.roles.includes('student')).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><label>${t('Course','หลักสูตร')}<select name="course">${examples.courses.map(c=>`<option value="${c.id}">${esc(courseTitle(c.id))}</option>`).join('')}</select></label></div><label>${t('Access period','ระยะเวลาสิทธิ์')}<select id="demo-period" name="period"><option value="date">${t('Fixed end date','วันสิ้นสุด')}</option><option value="duration">${t('Days from assignment','จำนวนวันจากมอบหมาย')}</option><option value="unlimited">${t('Unlimited — explicitly assigned','ไม่จำกัด — กำหนดโดยชัดแจ้ง')}</option></select></label><label id="demo-expiry-label">${t('End date / days','วันสิ้นสุด / จำนวนวัน')}<input required id="demo-expiry" name="expiry" type="date" value="2026-12-31"></label><button class="primary">${t('Assign sample access','มอบหมายสิทธิ์ตัวอย่าง')}</button></form></div>`;
if(page==='links')return `<div class="panel"><h2>${t('Verified relationships','ความสัมพันธ์ที่ยืนยันแล้ว')}</h2>${table([t('Parent','ผู้ปกครอง'),t('Student','นักเรียน'),t('Status','สถานะ')],examples.links.map(l=>[esc(examples.users.find(u=>u.id===l.parent)?.name),sampleName(l.student),l.verified?t('Approved','อนุมัติแล้ว'):t('Pending','รออนุมัติ')]))}<form id="demo-link"><label>${t('Parent','ผู้ปกครอง')}<select name="parent">${examples.users.filter(u=>u.roles.includes('parent')).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><label>${t('Student','นักเรียน')}<select name="student">${examples.users.filter(u=>u.roles.includes('student')).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><label class="question-option"><input type="checkbox" name="verified" required>${t('I have verified this fictional relationship (demo).','ยืนยันว่าตรวจสอบความสัมพันธ์สมมตินี้แล้ว (สาธิต)')}</label><button class="primary">${t('Approve sample link','อนุมัติความสัมพันธ์ตัวอย่าง')}</button></form></div>`;
if(page==='reports')return `<div class="panel"><h2>${t('Learning progress','พัฒนาการเรียนรู้')}</h2>${table([t('Student','นักเรียน'),t('Lessons complete','บทเรียนที่เสร็จ'),t('Quiz result','ผลแบบทดสอบ')],examples.users.filter(u=>u.roles.includes('student')).map(u=>[sampleName(u.id),personProgress(u.id)+'/8',u.id==='mek'?(examples.score??'—'):'—']))}</div>`;
if(page==='events')return `<div class="panel"><h2>Science Discovery Workshop</h2><p>${6+demo.registrations.filter(x=>!x.cancelled).length}/12 ${t('sample places','ที่นั่งตัวอย่าง')}</p>${demo.registrations.map((x,i)=>`<div class="task-row">DEMO-${i+1} <button class="button small" data-demo-cancel="${i}" ${x.cancelled?'disabled':''}>${x.cancelled?t('Cancelled','ยกเลิกแล้ว'):t('Cancel registration','ยกเลิกการลงทะเบียน')}</button></div>`).join('')||empty(t('No new demo registrations','ยังไม่มีการลงทะเบียนสาธิตใหม่'),t('Six fictional registrations are included in the starting count.','จำนวนเริ่มต้นรวมผู้ลงทะเบียนสมมติหกคน'))}<button class="primary" id="add-demo-registration" ${demo.registrations.filter(x=>!x.cancelled).length>=6?'disabled':''}>${t('Add sample registration','เพิ่มการลงทะเบียนตัวอย่าง')}</button></div>`;
if(page==='media')return demoMedia();if(page==='appearance')return demoBranding();if(page==='content')return `<div class="panel"><h2>${t('Bilingual sample content','เนื้อหาตัวอย่างสองภาษา')}</h2><form id="demo-content"><div class="two"><label>English<textarea name="en" required>${esc(examples.contentEn||'Small questions. Big discoveries.')}</textarea></label><label>ไทย<textarea name="th">${esc(examples.contentTh||'')}</textarea></label></div><button class="primary">${t('Save in demo','บันทึกในระบบสาธิต')}</button></form><p>${t('Public production content is never changed by this form.','แบบฟอร์มนี้ไม่เปลี่ยนเนื้อหาสาธารณะจริง')}</p><div class="message">${esc(lang==='th'?(examples.contentTh||examples.contentEn||'Small questions. Big discoveries.'):(examples.contentEn||'Small questions. Big discoveries.'))}</div></div>`;
if(page==='assessments')return `<div class="panel"><h2>${t('Forces & motion · sample assessment','แรงและการเคลื่อนที่ · แบบทดสอบตัวอย่าง')}</h2><p>${t('2 questions · pass score 60% · 2 attempts · answer review disabled.','2 ข้อ · ผ่าน 60% · ทำได้ 2 ครั้ง · ปิดการแสดงเฉลย')}</p><p>${t('Student results','ผลนักเรียน')}: ${examples.score===null?t('Not submitted','ยังไม่ส่ง'):examples.score+'%'}</p></div>`;
return `<div class="panel"><h2>${t('Demo settings','การตั้งค่าระบบสาธิต')}</h2><p>${t('All demo users and actions are fictional and isolated from server storage. Refreshing clears this demo.','ผู้ใช้และการดำเนินการทั้งหมดเป็นข้อมูลสมมติ แยกจากที่เก็บข้อมูลเซิร์ฟเวอร์ โหลดใหม่เพื่อล้างข้อมูลสาธิต')}</p>${button(t('Return to school website','กลับเว็บไซต์โรงเรียน'),'home','')}</div>`}
function demoMedia(){return `<div class="panel"><h2>${t('Try a local image preview','ลองดูตัวอย่างภาพในเครื่อง')}</h2><p>${t('No upload is sent. Files remain in this tab and cannot change the real media library.','ไม่มีการส่งไฟล์ ภาพอยู่ในแท็บนี้และไม่เปลี่ยนคลังสื่อจริง')}</p><label>${t('Choose JPEG, PNG, or WebP · up to 5 MB','เลือก JPEG, PNG หรือ WebP · ไม่เกิน 5 MB')}<input id="demo-image" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="grid">${examples.media.map(m=>`<figure><img src="${m.url}" alt="${esc(m.name)}" class="content-image"><figcaption>${esc(m.name)}</figcaption></figure>`).join('')}</div></div>`}
function demoBranding(){return `<div class="panel"><h2>${t('Preview a sample brand palette','ดูตัวอย่างชุดสีแบรนด์')}</h2><form id="demo-brand"><div class="color-grid">${[['primary',t('Primary','สีหลัก')],['secondary',t('Secondary','สีรอง')],['accent',t('Accent','สีเน้น')],['background',t('Background','พื้นหลัง')],['text',t('Text','ข้อความ')]].map(([k,label])=>`<label>${label}<input type="color" name="${k}" value="${examples.branding[k]}"></label>`).join('')}</div><div id="demo-color-preview" class="panel" style="background:${examples.branding.background};color:${examples.branding.text};border-top:10px solid ${examples.branding.primary}"><strong>Headstart Academics</strong><p style="color:inherit">${t('Preview only — the published website is unchanged.','ตัวอย่างเท่านั้น — เว็บไซต์จริงไม่เปลี่ยนแปลง')}</p></div><div id="demo-color-warning">${contrastMessage(examples.branding)}</div><button class="primary">${t('Save demo palette','บันทึกชุดสีสาธิต')}</button></form></div>`}
function teacherDemo(page,item){const assigned=examples.courses.filter(c=>c.teacher==='Mali'),works=examples.submissions.filter(w=>teacherCan(w.student,w.course));if(page==='overview')return `<div class="welcome-strip"><div><h2>${t('Good to see you, Mali.','ยินดีต้อนรับ ครูมะลิ')}</h2><p>${t('A little feedback can make a big difference.','ข้อเสนอแนะช่วยสร้างความเปลี่ยนแปลงได้')}</p></div>${button(t('Review homework','ตรวจการบ้าน'),'demo/teacher/assignments')}</div>${stats([[assigned.length,t('Assigned courses','หลักสูตรที่รับผิดชอบ')],[works.filter(w=>!w.returned).length,t('Awaiting review','รอตรวจ')],[examples.questions.filter(q=>teacherCan(q.student,q.course)&&!q.reply).length,t('Unanswered questions','คำถามที่ยังไม่ตอบ')],[examples.messages.filter(m=>teacherCan(m.student,m.course)&&!m.reply).length,t('Parent messages','ข้อความผู้ปกครอง')]])}<div class="grid"><div class="panel"><h3>${t('Next to review','งานที่รอตรวจ')}</h3>${works.filter(w=>!w.returned).map(w=>`<div class="task-row"><div><b>${sampleName(w.student)}</b><p>${t('Observation assignment','งานสังเกตสิ่งรอบตัว')}</p></div><a class="text-link" href="#demo/teacher/assignments/${w.id}">${t('Open','เปิด')} ↗</a></div>`).join('')||t('All caught up.','ตรวจครบแล้ว')}</div><div class="panel"><h3>${t('Students to check in with','นักเรียนที่ควรติดตาม')}</h3><p>${t('Mek has unfinished lessons in Science Explorer.','เมฆยังมีบทเรียนที่ไม่เสร็จใน Science Explorer')}</p><p>${t('Recent activity is not tracked in this demo; no attendance is inferred.','ระบบสาธิตไม่ติดตามกิจกรรมล่าสุด และไม่ใช้เป็นการเช็กชื่อ')}</p>${button(t('View students','ดูนักเรียน'),'demo/teacher/students','')}</div></div>`;
if(page==='courses')return `<div class="grid">${assigned.map(c=>`<div class="card card-body"><span class="tag">${t('Assigned to you','มอบหมายให้คุณ')}</span><h2>${esc(courseTitle(c.id))}</h2><p>${examples.assignments.filter(a=>a.course===c.id&&a.active).length} ${t('students','นักเรียน')}</p>${button(t('Review course work','ตรวจงานหลักสูตร'),'demo/teacher/assignments','')}</div>`).join('')}</div>`;
if(page==='students')return `<div class="panel">${table([t('Student','นักเรียน'),t('Course','หลักสูตร'),t('Progress','ความก้าวหน้า')],examples.assignments.filter(a=>a.active&&teacherCan(a.student,a.course)).map(a=>[sampleName(a.student),esc(courseTitle(a.course)),personProgress(a.student)+'/8']))}</div>`;
if(page==='assignments'){const w=works.find(w=>w.id===item)||works[0];return `<div class="grading-layout"><aside class="panel"><h3>${t('Submissions','งานที่ส่ง')}</h3>${works.map(s=>`<a class="lesson-row" href="#demo/teacher/assignments/${s.id}">${sampleName(s.student)}<small>${s.returned?t('Returned','ส่งคืนแล้ว'):t('Awaiting review','รอตรวจ')}</small></a>`).join('')}</aside><div class="panel">${w?`<span class="tag">${esc(courseTitle(w.course))}</span><h2>${sampleName(w.student)} · ${t('Observation assignment','งานสังเกต')}</h2><div class="message"><p>${esc(w.text)}</p>${w.file?`<p>${esc(w.file)} · ${t('local demo file only','ไฟล์สาธิตในเครื่องเท่านั้น')}</p>`:''}</div><form id="demo-grade" data-work="${w.id}"><label>${t('Score out of 10','คะแนนเต็ม 10')}<input type="number" name="score" min="0" max="10" step="0.5" required value="${w.score??''}"></label><label>${t('Feedback for the student','ข้อเสนอแนะให้นักเรียน')}<textarea required name="feedback" maxlength="2000">${esc(w.feedback)}</textarea></label><button class="primary">${t('Return sample work to student','ส่งงานตัวอย่างคืนให้นักเรียน')}</button></form>`:empty(t('No submissions','ยังไม่มีงานที่ส่ง'),t('Only your assigned students’ work appears here.','แสดงเฉพาะงานของนักเรียนที่ได้รับมอบหมาย'))}</div></div>`}
if(page==='media')return demoMedia();if(page==='questions')return conversationDemo('teacher','questions');if(page==='communication')return conversationDemo('teacher','messages');return `<div class="panel"><h2>${t('Assessment results','ผลแบบทดสอบ')}</h2><p>${t('Mek','เมฆ')} · Science Explorer · ${examples.score===null?t('Not submitted','ยังไม่ส่ง'):examples.score+'%'}</p></div>`}
function studentDemo(page,item){const assigned=examples.assignments.filter(a=>a.student==='mek'&&accessFor('mek',a.course));if(page==='overview')return `<div class="welcome-strip"><div><h2>${t('Ready for your next discovery, Mek?','พร้อมค้นพบสิ่งใหม่ไหม เมฆ?')}</h2><p>${t('Keep going, one lesson at a time.','ค่อย ๆ เรียนรู้ไปทีละบท')}</p></div>${assigned[0]?button(t('Continue Learning','เรียนต่อ'),'demo/student/learn/'+assigned[0].course):''}</div>${!assigned.length?empty(t('No courses have been assigned yet','ยังไม่มีหลักสูตรที่ได้รับมอบหมาย'),t('Your enrollment request needs administrator review. Contact the school for help.','คำขอเรียนต้องผ่านการตรวจสอบจากผู้ดูแล ติดต่อโรงเรียนเพื่อขอความช่วยเหลือ'))+button(t('Contact school','ติดต่อโรงเรียน'),'contact',''):`<div class="grid">${assigned.map(a=>learningCard(a)).join('')}<div class="card card-body"><span class="tag">${t('Next deadline','กำหนดส่งถัดไป')}</span><h2>${t('Observe the world around you','สังเกตโลกรอบตัว')}</h2><p>30 ${t('October 2026','ตุลาคม 2569')}</p>${button(t('Open assignment','เปิดงาน'),'demo/student/assignments','')}</div></div>`}<div class="panel"><h3>${t('Recent teacher feedback','ข้อเสนอแนะล่าสุดจากครู')}</h3>${returnedWork('mek')||t('No returned work yet. Your teacher’s feedback will appear here.','ยังไม่มีงานที่ส่งคืน ข้อเสนอแนะจากครูจะแสดงที่นี่')}</div>`;
if(page==='learn'){const id=item||assigned[0]?.course;if(!id||!accessFor('mek',id))return empty(t('Course access required','ต้องมีสิทธิ์หลักสูตร'),t('Catalog browsing does not grant access. An administrator must assign this course.','การดูรายการหลักสูตรไม่ให้สิทธิ์เรียน ผู้ดูแลต้องมอบหมายหลักสูตรนี้'));return `<div class="learning"><div><div class="video-demo"><video controls preload="none" aria-label="${t('Prerecorded lesson player','เครื่องเล่นบทเรียนที่บันทึกไว้')}"></video><p>${t('No approved lesson video has been uploaded. The player will work when a permitted video source is configured.','ยังไม่มีวิดีโอบทเรียนที่อนุมัติ เครื่องเล่นจะทำงานเมื่อกำหนดแหล่งวิดีโอที่มีสิทธิ์')}</p></div><div class="panel"><span class="tag">${esc(courseTitle(id))}</span><h2>${t('Lesson','บทที่')} ${examples.lesson+1} · ${t('Matter all around us','สสารรอบตัวเรา')}</h2><p>${t('Teaching language: Thai. Changing the interface does not translate videos or documents.','ภาษาที่ใช้สอน: ไทย การเปลี่ยนเมนูไม่ได้แปลวิดีโอหรือเอกสาร')}</p><button class="primary" id="demo-complete">${examples.complete.has(examples.lesson)?t('Undo sample completion','ยกเลิกสถานะเรียนจบตัวอย่าง'):t('Mark sample lesson complete','ทำเครื่องหมายเรียนจบตัวอย่าง')}</button><h3 style="margin-top:30px">${t('Learning materials','เอกสารประกอบ')}</h3><button class="button" id="download-demo">${t('Download sample worksheet','ดาวน์โหลดใบงานตัวอย่าง')} ↓</button><div class="actions">${button(t('Related assignment','งานที่เกี่ยวข้อง'),'demo/student/assignments','')}${button(t('Take sample quiz','ทำแบบทดสอบตัวอย่าง'),'demo/student/assessments','')}</div><h3>${t('Ask your teacher','ถามครู')}</h3>${questionForm()}</div></div><aside class="panel"><h3>${t('Module 1 · Explore','โมดูล 1 · สำรวจ')}</h3><p>${examples.complete.size}/8 ${t('lessons complete','บทเรียนที่เสร็จ')}</p>${Array.from({length:8},(_,i)=>`<button data-demo-lesson="${i}" class="lesson-row ${examples.lesson===i?'active':''}">${examples.complete.has(i)?'✓':'○'} ${t('Lesson','บทที่')} ${i+1}<small>${t('Prerecorded video pending','รอวิดีโอที่บันทึกไว้')}</small></button>`).join('')}</aside></div>`}
if(page==='questions')return conversationDemo('student','questions');if(page==='results')return `<div class="panel"><h2>${t('Your results','ผลของคุณ')}</h2><p>${t('Quiz score','คะแนนแบบทดสอบ')}: ${examples.score??'—'}${examples.score!==null?'%':''}</p>${returnedWork('mek')||t('No returned assignments yet.','ยังไม่มีงานที่ส่งคืน')}<h3>${t('Certificates','ใบประกาศ')}</h3>${examples.complete.size===8&&examples.score>=60?notice(t('Sample certificate criteria met: 8 lessons complete and quiz passed. This is demo eligibility, not an issued school certificate.','ผ่านเกณฑ์ใบประกาศตัวอย่าง: เรียนครบ 8 บทและสอบผ่าน เป็นสถานะสาธิต ไม่ใช่ใบประกาศของโรงเรียน')):empty(t('Keep learning','เรียนรู้ต่อไป'),t('Complete 8 lessons and pass the quiz with 60% to meet the sample completion rule.','เรียนครบ 8 บทและสอบผ่าน 60% เพื่อผ่านเกณฑ์สำเร็จตัวอย่าง'))}</div>`;
if(!accessFor('mek','science'))return empty(t('No assigned course','ยังไม่มีหลักสูตรที่มอบหมาย'),t('An administrator must assign access first.','ผู้ดูแลต้องมอบหมายสิทธิ์ก่อน'));if(page==='assignments')return `<div class="panel"><span class="tag">${t('Due 30 October 2026','กำหนดส่ง 30 ตุลาคม 2569')}</span><h2>${t('Observe the world around you','สังเกตโลกรอบตัว')}</h2><p>${t('Describe something you are curious about. How could you investigate it?','อธิบายสิ่งที่คุณสงสัย แล้วจะค้นหาคำตอบได้อย่างไร?')}</p><form id="demo-submit"><label>${t('Your answer','คำตอบ')}<textarea required maxlength="3000" name="answer"></textarea></label><label>${t('Optional file · PDF, PNG, JPEG · up to 5 MB','ไฟล์ไม่บังคับ · PDF, PNG, JPEG · ไม่เกิน 5 MB')}<input type="file" id="demo-work-file" accept=".pdf,.png,.jpg,.jpeg"></label><button class="primary">${t('Submit sample work','ส่งงานตัวอย่าง')}</button></form><p>${t('Kept only in this tab. No file is uploaded to production.','เก็บในแท็บนี้เท่านั้น ไม่มีการอัปโหลดไฟล์ไปยังระบบจริง')}</p></div>`;return quizDemo()}
function quizDemo(){return `<div class="panel"><h2>${t('Forces & motion','แรงและการเคลื่อนที่')}</h2><p>${t('Sample quiz · pass 60% · attempts','แบบทดสอบตัวอย่าง · ผ่าน 60% · จำนวนครั้ง')} ${examples.attempts}/2</p>${examples.score!==null?notice(t('Latest score: ','คะแนนล่าสุด: ')+examples.score+'%'):''}<form id="demo-quiz">${[[t('With constant force, doubling mass makes acceleration…','เมื่อแรงคงที่ เพิ่มมวลสองเท่าทำให้ความเร่ง…'),[t('Double','เพิ่มสองเท่า'),t('Half','ลดลงครึ่งหนึ่ง'),t('Unchanged','เท่าเดิม')]],[t('The SI unit of force is…','หน่วย SI ของแรงคือ…'),[t('Newton','นิวตัน'),t('Kilogram','กิโลกรัม'),t('Metre','เมตร')]]].map(([q,answers],i)=>`<fieldset><legend>${i+1}. ${q}</legend>${answers.map((a,j)=>`<label class="question-option"><input type="radio" name="q${i}" value="${j}" required>${a}</label>`).join('')}</fieldset>`).join('')}<button class="primary" ${examples.attempts>=2?'disabled':''}>${examples.attempts>=2?t('Attempt limit reached','ครบจำนวนครั้งแล้ว'):t('Submit sample answers','ส่งคำตอบตัวอย่าง')}</button></form><p>${t('Client-side demo scoring only. Not suitable for real exams; answer review is disabled.','คะแนนสาธิตคำนวณในเบราว์เซอร์ ไม่ใช้สอบจริง ปิดการแสดงเฉลย')}</p></div>`}
function returnedWork(student){return examples.submissions.filter(s=>s.student===student&&s.returned).map(s=>`<div class="message"><b>${esc(courseTitle(s.course))} · ${s.score}/10</b><p>${esc(s.feedback)}</p></div>`).join('')}
function parentDemo(page){const child=examples.child;if(!children().includes(child))return empty(t('No verified child links','ยังไม่มีความสัมพันธ์ที่ยืนยัน'),t('An administrator must approve the relationship before any student information can be shown.','ผู้ดูแลต้องอนุมัติความสัมพันธ์ก่อนแสดงข้อมูลนักเรียน'));const assigned=examples.assignments.filter(a=>a.student===child&&accessFor(child,a.course));if(page==='messages')return conversationDemo('parent','messages');if(page==='feedback')return `<div class="panel"><h2>${t('Feedback for','ข้อเสนอแนะสำหรับ')} ${sampleName(child)}</h2>${returnedWork(child)||empty(t('No feedback yet','ยังไม่มีข้อเสนอแนะ'),t('Feedback will appear after the teacher returns work.','ข้อเสนอแนะจะแสดงหลังครูส่งงานคืน'))}${button(t('Contact the teacher','ติดต่อครู'),'demo/parent/messages','')}</div>`;if(page==='work')return `<div class="panel"><h2>${t('Results & outstanding work','ผลและงานที่ยังไม่เสร็จ')}</h2><p>${t('Assessment result','ผลแบบทดสอบ')}: ${child==='mek'&&examples.score!==null?examples.score+'%':t('Not submitted','ยังไม่ส่ง')}</p><div class="task-row"><div><b>${t('Observation assignment','งานสังเกต')}</b><p>${t('Due 30 October 2026','กำหนดส่ง 30 ตุลาคม 2569')}</p></div><span class="tag">${examples.submissions.some(s=>s.student===child)?t('Submitted','ส่งแล้ว'):t('Outstanding','ยังไม่ส่ง')}</span></div>${returnedWork(child)}</div>`;return `<div class="parent-summary"><h2>${t('A quick look at','สรุปการเรียนรู้ของ')} ${sampleName(child)}</h2><p>${child==='mek'?t('Mek has completed '+examples.complete.size+' of 8 lessons. A little regular practice will keep the momentum going.','เมฆเรียนจบแล้ว '+examples.complete.size+' จาก 8 บท การฝึกฝนอย่างสม่ำเสมอช่วยให้เรียนต่อได้ดี'):t('Fah is ready to begin the assigned course. No lesson completions have been recorded in this demo.','ฟ้าพร้อมเริ่มหลักสูตรที่ได้รับมอบหมาย ยังไม่มีบทเรียนที่เรียนจบในระบบสาธิต')}</p></div><div class="grid">${assigned.map(a=>learningCard(a,child)).join('')||empty(t('No active course assignments','ไม่มีหลักสูตรที่ใช้งาน'),t('Contact the school about course access.','ติดต่อโรงเรียนเรื่องสิทธิ์หลักสูตร'))}<div class="card card-body"><h3>${t('Learning activity','กิจกรรมการเรียนรู้')}</h3><p>${personProgress(child)}/8 ${t('lessons complete','บทเรียนที่เสร็จ')}</p><p>${t('This describes lesson completion, not classroom attendance. No recent-activity timestamps are invented.','ข้อมูลนี้คือการเรียนจบบทเรียน ไม่ใช่การเช็กชื่อเข้าเรียน ไม่มีการสร้างเวลาใช้งานล่าสุดขึ้นเอง')}</p>${button(t('View results & work','ดูผลและงาน'),'demo/parent/work','')}</div></div><div class="panel"><h3>${t('Teacher feedback','ข้อเสนอแนะครู')}</h3>${returnedWork(child)||t('No feedback yet.','ยังไม่มีข้อเสนอแนะ')}${button(t('Message the teacher','ส่งข้อความถึงครู'),'demo/parent/messages','')}</div>`}
function questionForm(){return `<form id="demo-question"><label>${t('Your question','คำถามของคุณ')}<textarea required name="text" maxlength="1500"></textarea></label><button class="primary">${t('Post sample question','เพิ่มคำถามตัวอย่าง')}</button></form>`}
function conversationDemo(r,kind){const list=kind==='questions'?examples.questions:examples.messages;const visible=list.filter(m=>r==='teacher'?teacherCan(m.student,m.course):r==='parent'?children().includes(m.student)&&m.student===examples.child&&m.parent==='pat':m.student==='mek'&&accessFor('mek',m.course));return `<div class="panel"><h2>${kind==='questions'?t('Course questions','คำถามในหลักสูตร'):t('Conversations with the teacher','การพูดคุยกับครู')}</h2>${visible.map(m=>`<article class="message"><b>${sampleName(m.student)} · ${esc(courseTitle(m.course))}</b><p>${esc(m.text)}</p>${m.reply?`<div class="reply"><b>${t('Teacher reply','ครูตอบ')}</b><p>${esc(m.reply)}</p></div>`:r==='teacher'?`<form class="demo-reply" data-kind="${kind}" data-id="${m.id}"><label>${t('Reply','ตอบกลับ')}<textarea required name="reply" maxlength="1500"></textarea></label><button class="button">${t('Return sample reply','ส่งคำตอบตัวอย่าง')}</button></form>`:`<span class="tag gray">${t('Awaiting teacher reply','รอครูตอบ')}</span>`}</article>`).join('')||empty(t('No conversations yet','ยังไม่มีการสนทนา'),t('Only authorized course or linked-child conversations appear here.','แสดงเฉพาะการสนทนาในหลักสูตรหรือบุตรหลานที่มีสิทธิ์'))}${r==='student'?(accessFor('mek','science')?questionForm():''):r==='parent'?`<form id="demo-parent-message"><label>${t('Relevant course teacher','ครูประจำหลักสูตร')}<select name="course">${examples.assignments.filter(a=>a.student===examples.child&&a.active).map(a=>`<option value="${a.course}">${esc(courseTitle(a.course))} · ${esc(demoCourse(a.course)?.teacher||'')}</option>`).join('')}</select></label><label>${t('Message','ข้อความ')}<textarea required name="text" maxlength="1500"></textarea></label><button class="primary">${t('Add sample message','เพิ่มข้อความตัวอย่าง')}</button></form>`:''}</div>`}
function profileDemo(r){return `<div class="panel"><h2>${t('Sample profile','โปรไฟล์ตัวอย่าง')}</h2><form id="demo-profile">${field('name',t('Display name','ชื่อที่แสดง'),examples.profiles[r].name)}<label>${t('Learning notes','บันทึกการเรียนรู้')}<textarea name="bio" maxlength="1000">${esc(examples.profiles[r].bio)}</textarea></label><button class="primary">${t('Save sample profile','บันทึกโปรไฟล์ตัวอย่าง')}</button></form><p>${t('Assigned role','บทบาทที่ได้รับ')}: ${roleName(r)}</p><p>${t('You cannot change assigned permissions from a profile.','คุณไม่สามารถเปลี่ยนสิทธิ์ที่ได้รับจากหน้าโปรไฟล์')}</p></div>`}
function realPortal(page='overview'){if(!authChecked)return `<div class="container">${empty(t('Checking your account…','กำลังตรวจสอบบัญชี…'),t('Loading your assigned permissions.','กำลังโหลดสิทธิ์ที่ได้รับมอบหมาย'))}</div>`;if(!realRole()){history.replaceState(null,'','#login?next='+encodeURIComponent('portal/'+page));return schoolLogin()}const r=realRole(),menus=menuFor(r);if(!menus.some(([id])=>id===page)&&!['learn','grading','eventadmin','manage'].includes(page))return notFound();const permittedManagement=r==='admin'?['appearance','content','media']:r==='teacher'?['media']:[];let body;if(['appearance','content','media'].includes(page)&&!permittedManagement.includes(page))body=empty(t('Access restricted','จำกัดการเข้าถึง'),t('This page is not included in your assigned roles.','หน้านี้ไม่อยู่ในบทบาทที่คุณได้รับ'));else if(permittedManagement.includes(page)){demo.role=null;body=page==='appearance'?appearancePage():page==='content'?editorPage():mediaPage()}else if(page==='profile'||page==='settings')body=`<div class="panel"><h2>${t('Verified account','บัญชีที่ยืนยันแล้ว')}</h2><p>${t('Assigned roles','บทบาทที่ได้รับ')}: ${allowedRealRoles().map(roleName).join(', ')}</p><p>${t('Account identity is managed by ChatGPT. School profile editing is not connected.','ข้อมูลบัญชีจัดการผ่าน ChatGPT ยังไม่เชื่อมต่อการแก้ไขโปรไฟล์โรงเรียน')}</p><a class="button" href="/signout-with-chatgpt?return_to=%2F%23login" target="_top">${t('Log Out','ออกจากระบบ')}</a></div>`;else body=`<div class="panel"><h2>${t('Welcome to your dashboard','ยินดีต้อนรับสู่แดชบอร์ด')}</h2><p>${t('Your role has been verified on the server. School LMS records and email/password accounts are not connected yet; no sample figures are shown as real data.','เซิร์ฟเวอร์ยืนยันบทบาทของคุณแล้ว ยังไม่เชื่อมต่อข้อมูลระบบการเรียนและบัญชีอีเมล/รหัสผ่าน จึงไม่แสดงตัวเลขตัวอย่างเป็นข้อมูลจริง')}</p>${r==='admin'?`<div class="actions">${button(t('Edit website content','แก้ไขเนื้อหาเว็บไซต์'),'portal/content')}${button(t('Upload images','อัปโหลดภาพ'),'portal/media','')}${button(t('Website appearance','รูปลักษณ์เว็บไซต์'),'portal/appearance','')}</div>`:''}${r==='teacher'?button(t('Manage assigned course images','จัดการภาพหลักสูตรที่ได้รับมอบหมาย'),'portal/media'):''}<h3>${t('Explore the portal workflows','สำรวจขั้นตอนการทำงาน')}</h3><p>${t('Use the isolated demo to review user invitations, assignments, grading, family links, and learning.','ใช้ระบบสาธิตที่แยกต่างหากเพื่อทดสอบคำเชิญผู้ใช้ การมอบหมาย การตรวจงาน ความสัมพันธ์ครอบครัว และการเรียน')}</p>${button(t('Explore Demo','สำรวจระบบสาธิต'),'demo','')}</div>`;return `<div class="portal portal-v3"><aside class="sidebar"><div class="profile"><b>${roleName(r)}</b><small>${t('Verified account','บัญชีที่ยืนยันแล้ว')}</small></div>${menus.map(([id,title])=>`<a href="#portal/${id}" class="${page===id?'active':''}">${title}</a>`).join('')}<a href="#home">← ${t('School website','เว็บไซต์โรงเรียน')}</a></aside><div class="portal-content"><div class="portal-topbar"><h1>${menus.find(m=>m[0]===page)?.[1]||t('Dashboard','แดชบอร์ด')}</h1><div class="portal-controls"><div class="language-switch">${['en','th'].map(l=>`<button data-portal-lang="${l}" aria-pressed="${l===lang}">${l.toUpperCase()}</button>`).join('')}</div><a class="text-link" href="#portal/${r==='admin'?'settings':'profile'}">${t('Profile','โปรไฟล์')}</a></div></div>${allowedRealRoles().length>1?`<label>${t('Your authorized roles','บทบาทที่คุณได้รับอนุญาต')}<select id="real-role">${allowedRealRoles().map(v=>`<option value="${v}" ${v===r?'selected':''}>${roleName(v)}</option>`).join('')}</select></label>`:''}${body}</div></div>`}
updateShell=function(){baseShell();const signed=!!realRole();$('header').classList.toggle('signed-in',signed);$('.signin').textContent=signed?t('My Dashboard','แดชบอร์ดของฉัน'):t('Log In','เข้าสู่ระบบ');$('.signin').href=signed?'#portal/overview':'#login';$('.signin').classList.add('login-visible');$('header .global-account')?.remove();if(signed){const menu=document.createElement('details');menu.className='account-dropdown global-account';menu.innerHTML=`<summary aria-label="${t('Account menu','เมนูบัญชี')}"><span class="avatar small-avatar">${roleName(realRole())[0]}</span></summary><div><a href="#portal/${realRole()==='admin'?'settings':'profile'}">${t('Profile','โปรไฟล์')}</a><span>${t('Language','ภาษา')}</span><button data-account-lang="en">English</button><button data-account-lang="th">ไทย</button>${allowedRealRoles().length>1?allowedRealRoles().map(r=>`<button data-real-role="${r}">${roleName(r)}</button>`).join(''):''}<a href="/signout-with-chatgpt?return_to=%2F%23login" target="_top">${t('Log Out','ออกจากระบบ')}</a></div>`;$('header').append(menu)}$('nav').querySelector('a[href="#login"]').textContent=t('Log In','เข้าสู่ระบบ');};
render=function(){const [p,r,page,item]=route();if(!['login','register','reset','demo','portal'].includes(p)){baseRender();return}updateShell();main.innerHTML=p==='login'?schoolLogin():p==='register'||p==='reset'?accountScreen(p):p==='demo'?(r?demoPortal(r,page,item):chooseDemo()):realPortal(r);document.title=(p==='demo'?t('Demo — ','สาธิต — '):'')+t('Headstart Academics | Learning portal','Headstart Academics | พื้นที่การเรียนรู้');$('nav').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');$('#preview-banner').hidden=true;bind();installValidation()};
bind=function(){baseBind();document.querySelectorAll('[data-portal-lang],[data-account-lang]').forEach(b=>b.onclick=()=>switchLanguage(b.dataset.portalLang||b.dataset.accountLang));document.querySelectorAll('[data-real-role]').forEach(b=>b.onclick=()=>{if(allowedRealRoles().includes(b.dataset.realRole)){activeRealRole=b.dataset.realRole;location.hash='portal/overview';render()}});if($('#real-role'))$('#real-role').onchange=e=>{if(allowedRealRoles().includes(e.target.value)){activeRealRole=e.target.value;location.hash='portal/overview';render()}};
if($('#school-login')){const f=$('#school-login');$('#password-toggle').onclick=e=>{const input=f.elements.password,show=input.type==='password';input.type=show?'text':'password';e.target.textContent=show?t('Hide','ซ่อน'):t('Show','แสดง');e.target.setAttribute('aria-pressed',show)};f.onsubmit=async e=>{e.preventDefault();if(!validateForm(f)||schoolLoginBusy)return;schoolLoginBusy=true;const b=f.querySelector('button.primary');b.disabled=true;b.textContent=t('Checking…','กำลังตรวจสอบ…');f.setAttribute('aria-busy','true');await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));f.elements.password.value='';$('#login-error').innerHTML=notice(t('School sign-in is not configured. No credentials were sent. Use Explore Demo, or the verified management sign-in below.','ยังไม่ได้ตั้งค่าการเข้าสู่ระบบโรงเรียน ไม่มีการส่งข้อมูลบัญชี ใช้ระบบสาธิตหรือการเข้าสู่ระบบจัดการที่ยืนยันแล้วด้านล่าง'),true);schoolLoginBusy=false;b.disabled=false;b.textContent=t('Log In','เข้าสู่ระบบ');f.removeAttribute('aria-busy')}}
for(const id of ['password-reset','school-registration'])if($('#'+id))$('#'+id).onsubmit=e=>{e.preventDefault();if(!validateForm(e.target))return;$('#account-result').innerHTML=notice(t('Service not connected. No account was created and no email was sent. Your details were not transmitted.','ยังไม่เชื่อมต่อบริการ ไม่มีการสร้างบัญชีหรือส่งอีเมล ข้อมูลของคุณไม่ถูกส่งออก'),true)};if($('#registration-role'))$('#registration-role').onchange=e=>{const hidden=e.target.value==='parent';$('#registration-student').hidden=hidden;$('#registration-student').querySelectorAll('input').forEach(i=>i.disabled=hidden)};
if(!demoRoute())return;const r=route()[1];const save=(id,fn)=>{if($('#'+id))$('#'+id).onsubmit=e=>{e.preventDefault();if(!validateForm(e.target))return;const value=new FormData(e.target);if(fn(value,e.target)===false)return;render();toast('Saved in demo only. No production data changed.','บันทึกเฉพาะระบบสาธิต ไม่เปลี่ยนข้อมูลจริง')}};
save('demo-user',f=>{const email=f.get('email');if(!email.endsWith('@example.test')){toast('Use a fictional address ending in @example.test.','ใช้อีเมลสมมติที่ลงท้าย @example.test');return false}examples.users.push({id:crypto.randomUUID(),name:f.get('name'),email,roles:[f.get('role')]})});save('demo-roles',f=>{const u=examples.users.find(u=>u.id===f.get('user'));if(u&&!u.roles.includes(f.get('role')))u.roles.push(f.get('role'))});save('demo-course',f=>examples.courses.push({id:crypto.randomUUID(),title:pair(f.get('en'),f.get('th')),teacher:f.get('teacher'),published:f.get('status')==='published'}));
if($('#demo-period'))$('#demo-period').onchange=e=>{const i=$('#demo-expiry');i.disabled=e.target.value==='unlimited';i.type=e.target.value==='duration'?'number':'date';i.value=e.target.value==='duration'?'90':'2026-12-31';if(i.type==='number'){i.min='1';i.max='3650'}else{i.removeAttribute('min');i.removeAttribute('max')}};save('demo-access',f=>{let expiry=f.get('expiry');if(f.get('period')==='unlimited')expiry='unlimited';else if(f.get('period')==='duration'){const d=new Date();d.setDate(d.getDate()+Number(expiry));expiry=d.toISOString().slice(0,10)}const existing=examples.assignments.find(a=>a.student===f.get('student')&&a.course===f.get('course'));if(existing)Object.assign(existing,{active:true,expiry});else examples.assignments.push({student:f.get('student'),course:f.get('course'),expiry,active:true});examples.enrollment=examples.enrollment.filter(e=>e.student!==f.get('student')||e.course!==f.get('course'))});document.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=()=>{const a=examples.assignments[+b.dataset.revoke];a.active=!a.active;render()});save('demo-link',f=>{const old=examples.links.find(l=>l.parent===f.get('parent')&&l.student===f.get('student'));if(old)old.verified=true;else examples.links.push({parent:f.get('parent'),student:f.get('student'),verified:true})});save('demo-content',f=>{examples.contentEn=f.get('en');examples.contentTh=f.get('th')});
if($('#demo-brand')){const f=$('#demo-brand');f.oninput=()=>{const a=Object.fromEntries(new FormData(f));$('#demo-color-preview').style.background=a.background;$('#demo-color-preview').style.color=a.text;$('#demo-color-preview').style.borderTopColor=a.primary;$('#demo-color-warning').innerHTML=contrastMessage(a)};save('demo-brand',f=>{const a=Object.fromEntries(f);if(brandWarnings(a).length){toast('Fix low contrast before saving the sample palette.','แก้ความเปรียบต่างต่ำก่อนบันทึกชุดสีตัวอย่าง');return false}examples.branding={...examples.branding,...a}})}
if($('#demo-image'))$('#demo-image').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const result=await optimized(file);examples.media.push({name:file.name,url:URL.createObjectURL(result.blob)});render();toast('Local demo preview ready. Nothing uploaded.','ตัวอย่างภาพในเครื่องพร้อมแล้ว ไม่มีการอัปโหลด')}catch{toast('Choose a valid JPEG, PNG, or WebP image up to 5 MB.','เลือกภาพ JPEG, PNG หรือ WebP ที่ถูกต้อง ไม่เกิน 5 MB')}};
if($('#add-demo-registration'))$('#add-demo-registration').onclick=()=>{if(demo.registrations.filter(v=>!v.cancelled).length<6)demo.registrations.push({cancelled:false});render()};document.querySelectorAll('[data-demo-cancel]').forEach(b=>b.onclick=()=>{demo.registrations[+b.dataset.demoCancel].cancelled=true;render()});
save('demo-grade',(f,form)=>{const w=examples.submissions.find(w=>w.id===form.dataset.work);if(r!=='teacher'||!w||!teacherCan(w.student,w.course))return false;w.score=+f.get('score');w.feedback=f.get('feedback');w.returned=true});save('demo-submit',f=>{if(!accessFor('mek','science'))return false;const file=$('#demo-work-file').files[0];if(file&&(!/\.(pdf|jpe?g|png)$/i.test(file.name)||file.size>5*1024*1024)){toast('Choose PDF, JPEG or PNG, up to 5 MB.','เลือก PDF, JPEG หรือ PNG ไม่เกิน 5 MB');return false}examples.submissions.push({id:crypto.randomUUID(),student:'mek',course:'science',text:f.get('answer'),file:file?.name||'',score:null,feedback:'',returned:false})});
if($('#demo-complete'))$('#demo-complete').onclick=()=>{if(!accessFor('mek',route()[3]||'science'))return;examples.complete.has(examples.lesson)?examples.complete.delete(examples.lesson):examples.complete.add(examples.lesson);render()};document.querySelectorAll('[data-demo-lesson]').forEach(b=>b.onclick=()=>{examples.lesson=+b.dataset.demoLesson;render()});if($('#download-demo'))$('#download-demo').onclick=()=>{const blob=new Blob([t('HEADSTART — SAMPLE WORKSHEET\n\nWhat do you observe?\nWhat question would you ask?\nHow could you test your idea?\n\nDemo material only.','HEADSTART — ใบงานตัวอย่าง\n\nคุณสังเกตเห็นอะไร?\nคุณอยากถามอะไร?\nจะทดลองความคิดของคุณอย่างไร?\n\nเอกสารสาธิตเท่านั้น')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Headstart-sample-worksheet.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
save('demo-quiz',f=>{if(examples.attempts>=2||!accessFor('mek','science'))return false;examples.score=(f.get('q0')==='1'?50:0)+(f.get('q1')==='0'?50:0);examples.attempts++});save('demo-question',f=>{if(!accessFor('mek','science'))return false;examples.questions.push({id:crypto.randomUUID(),student:'mek',course:'science',text:f.get('text'),reply:''})});save('demo-parent-message',f=>{if(!children().includes(examples.child)||!examples.assignments.some(a=>a.student===examples.child&&a.course===f.get('course')&&a.active))return false;examples.messages.push({id:crypto.randomUUID(),parent:'pat',student:examples.child,course:f.get('course'),text:f.get('text'),reply:''})});document.querySelectorAll('.demo-reply').forEach(form=>form.onsubmit=e=>{e.preventDefault();if(!validateForm(form))return;const list=form.dataset.kind==='questions'?examples.questions:examples.messages,m=list.find(m=>m.id===form.dataset.id);if(r!=='teacher'||!m||!teacherCan(m.student,m.course))return;m.reply=new FormData(form).get('reply');render();toast('Demo reply saved; no message sent.','บันทึกคำตอบสาธิตแล้ว ไม่ได้ส่งข้อความจริง')});if($('#demo-child'))$('#demo-child').onchange=e=>{if(children().includes(e.target.value)){examples.child=e.target.value;render()}};save('demo-profile',f=>{examples.profiles[r].name=f.get('name');examples.profiles[r].bio=f.get('bio')});};
